import 'package:flutter/material.dart';

import 'harness_colors.dart';
import 'harness_tokens.dart';

/// The Harness pictorial mark, rendered from the generated brand asset.
///
/// The mark is a weaver's reed: a closed rectangular frame with evenly spaced
/// vertical threads, one driven past the top edge and continuing as a short
/// stub. Assets are generated by `tool/generate_branding_assets.ps1` from the
/// geometry in `docs/Harness/branding.md`; the interface never redraws it.
///
/// Two inks ship for the single-tone reversal rule: `mark-light` for light
/// surfaces and `mark-dark` for dark surfaces. Set [accented] for the empty
/// state, where the raised thread alone carries `primary-500`.
class HarnessMark extends StatelessWidget {
  /// Rendered edge length in logical pixels.
  final double size;

  /// Whether the raised thread uses the accent asset.
  final bool accented;

  /// Accessible name; pass `null` when the mark sits beside a visible wordmark.
  final String? semanticLabel;

  const HarnessMark({
    super.key,
    this.size = HarnessSize.iconLg,
    this.accented = false,
    this.semanticLabel,
  });

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final asset = size <= 20
        ? (isDark ? 'mark-small-dark.png' : 'mark-small-light.png')
        : accented
            ? (isDark ? 'mark-active-dark.png' : 'mark-active-light.png')
            : (isDark ? 'mark-dark.png' : 'mark-light.png');

    final image = Image.asset(
      'assets/branding/$asset',
      width: size,
      height: size,
      fit: BoxFit.contain,
      filterQuality: FilterQuality.high,
      gaplessPlayback: true,
      excludeFromSemantics: true,
    );

    if (semanticLabel == null) return image;
    return Semantics(label: semanticLabel, image: true, child: image);
  }
}

/// The `Harness` wordmark in Geist Sans SemiBold, sentence case, tracking -1%.
class HarnessWordmark extends StatelessWidget {
  /// Type size; tracking scales with it.
  final double fontSize;

  /// Ink for the name. Defaults to the theme's primary text color.
  final Color? color;

  const HarnessWordmark({
    super.key,
    this.fontSize = 18,
    this.color,
  });

  @override
  Widget build(BuildContext context) {
    final colors = HarnessColors.of(context);
    return Text(
      'Harness',
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: TextStyle(
        fontFamily: HarnessType.sans,
        fontSize: fontSize,
        fontWeight: FontWeight.w600,
        height: 1,
        letterSpacing: fontSize * -0.01,
        color: color ?? colors.textPrimary,
      ),
    );
  }
}

/// Mark plus wordmark, either leading (horizontal) or stacked (vertical).
class HarnessLockup extends StatelessWidget {
  /// The direction the lockup reads in.
  final Axis axis;

  /// Mark edge length.
  final double markSize;

  /// Wordmark size.
  final double fontSize;

  /// Space between mark and name.
  final double gap;

  /// Optional wordmark ink.
  final Color? color;

  const HarnessLockup({
    super.key,
    this.axis = Axis.horizontal,
    this.markSize = 20,
    this.fontSize = 18,
    this.gap = HarnessSpace.sm,
    this.color,
  });

  @override
  Widget build(BuildContext context) {
    final mark = HarnessMark(size: markSize);
    final word = HarnessWordmark(fontSize: fontSize, color: color);

    if (axis == Axis.horizontal) {
      return Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          mark,
          SizedBox(width: gap),
          Flexible(child: word),
        ],
      );
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        mark,
        SizedBox(height: gap),
        word,
      ],
    );
  }
}
